package com.sliit.eventsphere.service;

import com.sliit.eventsphere.dto.AnnouncementRequest;
import com.sliit.eventsphere.dto.AnnouncementResponse;
import com.sliit.eventsphere.security.ActingUser;

import java.util.List;

/**
 * Function 4 (Notification &amp; Communication): announcements written by
 * a person, rather than generated by the system.
 *
 * WHY THIS NEEDS AN APPROVAL STEP AT ALL
 *
 * The other ten notification types are produced by services reacting to
 * something they just committed, so their wording is bounded by the code
 * that produces them. An announcement is free text an Organizer writes,
 * delivered straight into every attendee's inbox, and nobody else would
 * see it before they did. The gate is the point of the feature, not
 * decoration on it.
 *
 * WHO CAN DO WHAT
 *
 *   Organizer  - writes and edits a draft on their OWN event, submits it,
 *                and waits. Cannot publish. There is no route that would
 *                let them, and the service refuses even if one appeared.
 *   Admin      - does everything an organizer can, on any event, and is
 *                the only role that can approve, reject, or publish.
 *
 * An Administrator's own announcement goes out directly, because they are
 * the approver - routing their draft into a queue they approve themselves
 * would be ceremony rather than control. That is the same reasoning the
 * event lifecycle already uses.
 */
public interface AnnouncementService {

    /**
     * CREATE. Starts a DRAFT on an event the actor manages.
     *
     * Always a draft, whoever is calling. An administrator publishes with
     * a second, explicit action rather than by passing a flag here - so
     * "this went out" is always a decision somebody took on purpose.
     */
    AnnouncementResponse create(Long eventId, AnnouncementRequest request, ActingUser actor);

    /** READ: every announcement on one event, newest first. Managers only. */
    List<AnnouncementResponse> getForEvent(Long eventId, ActingUser actor);

    /** READ: one announcement. Its author, the event's manager, or an admin. */
    AnnouncementResponse getById(Long announcementId, ActingUser actor);

    /** READ: the administrator's approval queue, oldest submission first. */
    List<AnnouncementResponse> getPendingApproval(ActingUser actor);

    /** READ: how many are waiting, for the badge on the admin sidebar. */
    long countPendingApproval(ActingUser actor);

    /**
     * UPDATE. Changes the title and message.
     *
     * Only while the announcement is DRAFT or REJECTED. A submitted one is
     * frozen because an administrator is reading it, and a published one
     * because people have already received the old text - editing it
     * afterwards would make the record disagree with the message in their
     * inbox.
     */
    AnnouncementResponse update(Long announcementId, AnnouncementRequest request, ActingUser actor);

    /** UPDATE: DRAFT or REJECTED becomes PENDING_APPROVAL. */
    AnnouncementResponse submitForApproval(Long announcementId, ActingUser actor);

    /**
     * UPDATE: PENDING_APPROVAL becomes PUBLISHED, and the message is
     * delivered in the same transaction. Administrator only.
     */
    AnnouncementResponse approveAndPublish(Long announcementId, ActingUser actor);

    /** UPDATE: PENDING_APPROVAL becomes REJECTED, with a reason. Administrator only. */
    AnnouncementResponse reject(Long announcementId, String reason, ActingUser actor);

    /**
     * UPDATE: an administrator's own shortcut - DRAFT straight to
     * PUBLISHED, skipping the queue. Administrator only.
     */
    AnnouncementResponse publishDirectly(Long announcementId, ActingUser actor);

    /**
     * DELETE. Only while it has not been published.
     *
     * A published announcement produced notifications sitting in people's
     * inboxes; deleting the record would leave those messages with no
     * explanation of where they came from or who approved them.
     */
    void delete(Long announcementId, ActingUser actor);
}
